create table agency_office_sessions(
 id text primary key,tenant_id text not null,package_id text not null,document_id text not null,source_revision_id text not null,source_file_version_id text not null,source_hash text not null,base_version bigint not null,basis_hash text not null,document_key text not null unique,source_ticket_hash text not null,
 state text not null default 'active' check(state in ('active','ready','adopted','cancelled','expired')),version bigint not null default 1,expires_at timestamptz not null,last_error text not null default '',adopted_revision_id text,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,document_id) references agency_documents(tenant_id,id),foreign key(tenant_id,source_file_version_id) references agency_file_versions(tenant_id,id));
create unique index agency_office_one_editor on agency_office_sessions(tenant_id,document_id) where state in ('active','ready');
create table agency_office_saves(id text primary key,tenant_id text not null,session_id text not null,ordinal int not null,file_version_id text not null,file_hash text not null,callback_hash text not null,callback_status int not null check(callback_status in (2,6)),created_at timestamptz not null default now(),unique(tenant_id,id),unique(tenant_id,session_id,callback_hash),unique(tenant_id,session_id,ordinal),foreign key(tenant_id,session_id) references agency_office_sessions(tenant_id,id),foreign key(tenant_id,file_version_id) references agency_file_versions(tenant_id,id));
create table agency_office_events(id text primary key,tenant_id text not null,session_id text not null,callback_hash text not null,status int not null,note text not null,created_at timestamptz not null default now(),unique(tenant_id,session_id,callback_hash),foreign key(tenant_id,session_id) references agency_office_sessions(tenant_id,id));
